  ref: string,
  button?: "left" | "right" | "middle",
  count?: 1 | 2,
  modifiers?: Array<"Alt" | "Control" | "Meta" | "Shift">,
}): Promise<{
  /** @pattern ^tab_[a-f0-9-]{36}$ */
  id: string,
  /** @maxLength 16384 */
  url: string,
  /** @maxLength 2048 */
  title: string,
  loading: boolean,
  /** @maxLength 2048 */
  loadError?: string,
  canGoBack: boolean,
  canGoForward: boolean,
  /** @integer @minimum 0 */
  generation: number,
}> // Click a ref from this tab's latest snapshot. Supports double/right/middle clicks and modifier keys.
  - tools.browser.console({
  /**
   * Exact tab ID returned by browser.tabs.open/list. Focus does not select a tool target.
   * @pattern ^tab_[a-f0-9-]{36}$
   */
  tabID: string,
  level?: "debug" | "info" | "warning" | "error",
  /** @integer @minimum 1 @maximum 500 */
  limit?: number,
}): Promise<{
  tab: {
    /** @pattern ^tab_[a-f0-9-]{36}$ */
    id: string,
    /** @maxLength 16384 */
    url: string,
    /** @maxLength 2048 */
    title: string,
    loading: boolean,
    /** @maxLength 2048 */
    loadError?: string,
    canGoBack: boolean,
    canGoForward: boolean,
    /** @integer @minimum 0 */
    generation: number,
  },
  messages: Array<{
      /** @maxLength 2048 */
      id: string,
      timestampMs: number,
      level: "debug" | "info" | "warning" | "error",
      /** @maxLength 100000 */
      text: string,
      textTruncated: boolean,
      source?: {
        /** @maxLength 100000 */
        url: string,
        /** @integer @minimum 0 */
        line: number,
        /** @integer @minimum 0 */
        column: number,
      },
    }>,
  truncated: boolean,
  /** @integer @minimum 0 */
  dropped: number,
}> // Read bounded console messages and uncaught errors for this tab's current document. Level includes more severe message...

